function registerUserPower(server, rpc) {
  server.registerTool("dexe_vote_user_power", {
    title: "User staking + delegation power across VoteTypes",
    description: "Reads `tokenBalance` and `nftBalance` on GovUserKeeper for every VoteType (Personal/Micropool/Delegated/Treasury). One multicall round-trip.",
    inputSchema: {
      govPool: external_exports.string().describe("GovPool contract address"),
      user: external_exports.string().describe("User wallet address"),
      chainId: chainIdParam
    },
    outputSchema: {
      govPool: external_exports.string(),
      user: external_exports.string(),
      userKeeper: external_exports.string(),
      power: external_exports.record(external_exports.object({
        tokenBalance: external_exports.string(),
        tokenOwned: external_exports.string(),
        nftBalance: external_exports.string(),
        nftOwned: external_exports.string()
      }))
    }
  }, async ({ govPool, user, chainId }) => {
    if (!isAddress(govPool))
      return errorResult5(`Invalid GovPool: ${govPool}`);
    if (!isAddress(user))
      return errorResult5(`Invalid user: ${user}`);
    try {
      const pr = rpc.tryProvider(chainId);
      if ("error" in pr)
        return errorResult5(`${pr.error}
${pr.remediation}`);
      const provider = pr.ok;
      const gp = new Interface(GOV_POOL_HELPERS_ABI);
      const uk = new Interface(USER_KEEPER_ABI);
      const [helpersR] = await multicall(provider, [
        { target: govPool, iface: gp, method: "getHelperContracts", args: [] }
      ]);
      if (!helpersR?.success)
        return errorResult5("getHelperContracts reverted");
      const userKeeper = helpersR.value.userKeeper;
      const calls = [];
      for (let vt2 = 0; vt2 < VOTE_TYPE_NAMES.length; vt2++) {
        calls.push({
          target: userKeeper,
          iface: uk,
          method: "tokenBalance",
          args: [user, vt2],
          allowFailure: true
        });
        calls.push({
          target: userKeeper,
          iface: uk,
          method: "nftBalance",
          args: [user, vt2],
          allowFailure: true
        });
      }
      const results = await multicall(provider, calls);
      const power = {};
      for (let vt2 = 0; vt2 < VOTE_TYPE_NAMES.length; vt2++) {
        const tb = results[vt2 * 2];
        const nb = results[vt2 * 2 + 1];
        const tbv = tb?.success ? tb.value : null;
        const nbv = nb?.success ? nb.value : null;
        const pick2 = (v7) => {
          if (!v7)
            return ["0", "0"];
          if (Array.isArray(v7))
            return [v7[0].toString(), v7[1].toString()];
          return [v7.balance.toString(), v7.ownedBalance.toString()];
        };
        const [tBal, tOwn] = pick2(tbv);
        const [nBal, nOwn] = pick2(nbv);
        power[VOTE_TYPE_NAMES[vt2]] = {
          tokenBalance: tBal,
          tokenOwned: tOwn,
          nftBalance: nBal,
          nftOwned: nOwn
        };
      }
      const structured = { govPool, user, userKeeper, power };
      const lines = VOTE_TYPE_NAMES.map((name2) => {
        const p4 = power[name2];
        return `  ${name2.padEnd(14)} token=${p4.tokenBalance} (owned=${p4.tokenOwned})  nft=${p4.nftBalance} (owned=${p4.nftOwned})`;
      });
      return {
        content: [
          {
            type: "text",
            text: `Voting power for ${user} on ${govPool}
UserKeeper: ${userKeeper}
${lines.join("\n")}`
          }
        ],
        structuredContent: structured
      };
    } catch (err13) {
      return errorResult5(toActionableError(err13, "dexe_vote_user_power").message);
    }
  });
}
