// dist/lib/merkleTree.js
init_lib2();
var coder = AbiCoder.defaultAbiCoder();
function leafHash(types, values) {
  const inner = keccak256(coder.encode(types, values));
  return keccak256(concat([inner]));
}
function commutative(a3, b6) {
  const ab = getBytes(a3);
  const bb = getBytes(b6);
  let cmp = 0;
  for (let i3 = 0; i3 < ab.length && cmp === 0; i3++) {
    cmp = (ab[i3] ?? 0) - (bb[i3] ?? 0);
  }
  return cmp <= 0 ? keccak256(concat([a3, b6])) : keccak256(concat([b6, a3]));
}
function buildMerkleTree(entries, leafEncoding) {
  if (entries.length === 0) {
    throw new Error("buildMerkleTree: entries must not be empty");
  }
  const original = entries.map((vals) => leafHash(leafEncoding, vals));
  const indexed = original.map((h3, i3) => ({ h: h3, i: i3 })).sort((a3, b6) => a3.h < b6.h ? -1 : a3.h > b6.h ? 1 : 0);
  const n4 = indexed.length;
  const treeSize = n4 === 1 ? 1 : 2 * n4 - 1;
  const tree = new Array(treeSize).fill("0x");
  for (let i3 = 0; i3 < n4; i3++)
    tree[n4 - 1 + i3] = indexed[i3].h;
  for (let i3 = n4 - 2; i3 >= 0; i3--) {
    tree[i3] = commutative(tree[2 * i3 + 1], tree[2 * i3 + 2]);
  }
  const sortedToOriginal = indexed.map(({ i: i3 }) => i3);
  const originalToSorted = new Array(n4).fill(0);
  for (let s2 = 0; s2 < n4; s2++)
    originalToSorted[sortedToOriginal[s2]] = s2;
  function siblingPath(leafSortedIdx) {
    const proof = [];
    let node2 = n4 - 1 + leafSortedIdx;
    while (node2 > 0) {
      const sibling = node2 % 2 === 0 ? node2 - 1 : node2 + 1;
      proof.push(tree[sibling]);
      node2 = Math.floor((node2 - 1) / 2);
    }
    return proof;
  }
  const proofs = new Array(n4);
  for (let original_i = 0; original_i < n4; original_i++) {
    proofs[original_i] = siblingPath(originalToSorted[original_i]);
  }
  return {
    root: hexlify(tree[0]),
    proofs,
    leafHashes: indexed.map(({ h: h3 }) => h3)
  };
}
function buildAddressMerkleTree(addresses) {
  const entries = addresses.map((a3) => [a3]);
  return buildMerkleTree(entries, ["address"]);
}
function verifyProof(proof, root2, leaf) {
  let computed = leaf;
  for (const sibling of proof)
    computed = commutative(computed, sibling);
  return computed.toLowerCase() === root2.toLowerCase();
}
function computeLeafHash(values, leafEncoding) {
  return leafHash(leafEncoding, values);
}

// dist/lib/amount.js
function parseUintString(value, field = "amount") {
  if (typeof value !== "string" || !/^[0-9]+$/.test(value)) {
    throw new Error(`Invalid ${field}: ${JSON.stringify(value)}. Expected a base-10 wei/id integer string \u2014 digits only, no decimals, hex (0x\u2026), sign, whitespace, or empty value.`);
  }
  return BigInt(value);
}

