var DECIMALS_IFACE = new Interface(["function decimals() view returns (uint8)"]);
async function resolveTokenAmount(amount, token, deps, opts) {
  const s2 = amount.trim();
  if (/^\d+$/.test(s2))
    return BigInt(s2);
  if (opts?.isNative)
    return parseAmount(s2, 18);
  const pr = new RpcProvider(deps.ctx.config).tryProvider(deps.chainId);
  if ("error" in pr) {
    throw new Error(`Amount '${amount}' is in human units, which needs an RPC to read the token's decimals \u2014 and no RPC is configured for chain ${deps.chainId}. Either pass the raw smallest-unit amount (digits only) or configure an RPC. ${pr.remediation}`);
  }
  const res = await multicall(pr.ok, [
    { target: token, iface: DECIMALS_IFACE, method: "decimals", args: [], allowFailure: true }
  ]);
  const decimals = res[0].success ? Number(res[0].value) : 18;
  return parseAmount(s2, decimals);
}
