function settingsRisk(entries, floorPct) {
  const advisories = entries.flatMap((s2, i3) => settingsAdvisories(s2, floorPct).map((a3) => entries.length > 1 ? `settings[${i3}]: ${a3}` : a3));
  if (advisories.length === 0)
    return {};
  const worst = entries.reduce((acc, s2) => {
    if (acc === "DANGER" || s2.quorum === void 0)
      return acc;
    return judgeQuorum(quorumPctFromRaw(s2.quorum), floorPct) === "DANGER" ? "DANGER" : acc;
  }, "CAUTION");
  return { advisories, risk: worst };
}
