async function validatorQuorumReachability(p4, deps) {
  const pr = new RpcProvider(deps.ctx.config).tryProvider(deps.chainId);
  if ("error" in pr)
    return void 0;
  const provider = pr.ok;
  const validatorsIface = new Interface([
    "function govValidatorsToken() view returns (address)"
  ]);
  const govPoolIface = new Interface([
    "function getHelperContracts() view returns (address settings, address userKeeper, address validators, address poolRegistry, address votePower)"
  ]);
  const [tokenRes, helpersRes] = await multicall(provider, [
    { target: p4.govValidators, iface: validatorsIface, method: "govValidatorsToken", args: [], allowFailure: true },
    { target: deps.govPool, iface: govPoolIface, method: "getHelperContracts", args: [], allowFailure: true }
  ]);
  if (!tokenRes?.success || !helpersRes?.success)
    return void 0;
  const tokenAddr = tokenRes.value;
  const settingsAddr = helpersRes.value[0];
  const erc20Iface = new Interface([
    "function totalSupply() view returns (uint256)",
    "function balanceOf(address) view returns (uint256)"
  ]);
  const settingsIface = new Interface([
    "function getDefaultSettings() view returns (tuple(bool earlyCompletion, bool delegatedVotingAllowed, bool validatorsVote, uint64 duration, uint64 durationValidators, uint64 executionDelay, uint128 quorum, uint128 quorumValidators, uint256 minVotesForVoting, uint256 minVotesForCreating, tuple(address rewardToken, uint256 creationReward, uint256 executionReward, uint256 voteRewardsCoefficient) rewardsInfo, string executorDescription))"
  ]);
  const reads = await multicall(provider, [
    { target: tokenAddr, iface: erc20Iface, method: "totalSupply", args: [], allowFailure: true },
    { target: settingsAddr, iface: settingsIface, method: "getDefaultSettings", args: [], allowFailure: true },
    ...p4.changes.map((c4) => ({
      target: tokenAddr,
      iface: erc20Iface,
      method: "balanceOf",
      args: [c4.user],
      allowFailure: true
    }))
  ]);
  const [supplyRes, defRes, ...balanceReads] = reads;
  if (!supplyRes?.success || !defRes?.success)
    return void 0;
  let newTotal = supplyRes.value;
  let largestChanged = 0n;
  for (let i3 = 0; i3 < p4.changes.length; i3++) {
    const cur = balanceReads[i3]?.success ? balanceReads[i3].value : 0n;
    const next = BigInt(p4.changes[i3].balance);
    newTotal = newTotal - cur + next;
    if (next > largestChanged)
      largestChanged = next;
  }
  if (newTotal === 0n) {
    return ["All validator balances end at 0 \u2014 the validator stage can never reach quorum again."];
  }
  const quorumPct = defRes.value[7];
  const needed = (newTotal * quorumPct + (10n ** 27n - 1n)) / 10n ** 27n;
  if (largestChanged < needed) {
    return [
      `After this change the external validator quorum needs ${needed} of ${newTotal} validator-token wei, and the largest CHANGED validator holds only ${largestChanged}. If no untouched validator meets the bar alone, passing any validator round will require multiple active validators \u2014 inactive or lost-key seats can stall the DAO's validator stage for every future proposal. Verify enough active validators jointly exceed the quorum before executing. [governance-safety advisory]`
    ];
  }
  return void 0;
}
