async function resolveStakingProposal(deps) {
  const pr = new RpcProvider(deps.ctx.config).tryProvider(deps.chainId);
  if ("error" in pr) {
    throw new Error(`stakingProposal was omitted (auto-resolve needs an RPC) and no RPC is configured for chain ${deps.chainId}. Pass stakingProposal explicitly (source: GovUserKeeper.stakingProposalAddress()) or configure an RPC. ${pr.remediation}`);
  }
  const [helpersR] = await multicall(pr.ok, [
    { target: deps.govPool, iface: STAKING_RESOLVER_IFACE, method: "getHelperContracts", args: [], allowFailure: true }
  ]);
  if (!helpersR?.success)
    throw new Error(`Could not read getHelperContracts() on GovPool ${deps.govPool}.`);
  const userKeeper = helpersR.value.userKeeper;
  const [stakingR] = await multicall(pr.ok, [
    { target: userKeeper, iface: STAKING_RESOLVER_IFACE, method: "stakingProposalAddress", args: [], allowFailure: true }
  ]);
  if (!stakingR?.success) {
    throw new Error(`stakingProposalAddress() reverted on GovUserKeeper ${userKeeper} \u2014 this pool's deployed UserKeeper implementation predates staking support, so staking proposals are unavailable for this DAO (protocol limitation, not a config issue). If you are sure staking exists here, pass stakingProposal explicitly.`);
  }
  const staking = stakingR.value;
  if (!staking || staking === ZeroAddress) {
    const deployData = STAKING_RESOLVER_IFACE.encodeFunctionData("deployStakingProposal", []);
    throw new Error(`This DAO has no StakingProposal deployed yet \u2014 GovUserKeeper.stakingProposalAddress() is the zero address. Deploy it first with ONE direct transaction (permissionless, NOT a governance proposal \u2014 do not wrap it in custom/custom_abi): call dexe_tx_send with exactly {"to":"${userKeeper}","data":"${deployData}","value":"0","chainId":${deps.chainId}} and then re-run this SAME call.`);
  }
  return staking;
}
var createStakingTierBuilder = {
  schema: external_exports.object({
    stakingProposal: external_exports.string().optional().describe("StakingProposal contract address. Omit to auto-resolve via the DAO's GovUserKeeper.stakingProposalAddress() (frontend parity); if it is not deployed yet you get the deployStakingProposal() remediation."),
    rewardToken: external_exports.string(),
    rewardAmount: numericIntString.describe("Reward amount in raw smallest units (wei)"),
    startedAt: numericIntString.describe("Unix seconds"),
    deadline: numericIntString.describe("Unix seconds"),
    stakingMetadataUrl: external_exports.string().describe("ipfs://<cid> of staking-specific metadata"),
    isNative: external_exports.boolean().default(false)
  }),
  async build(raw, deps) {
    const p4 = raw;
    const stakingProposal = p4.stakingProposal ?? await resolveStakingProposal(deps);
    if (!isAddress(stakingProposal))
      throw new Error(`Invalid stakingProposal: ${stakingProposal}`);
    if (!isAddress(p4.rewardToken))
      throw new Error(`Invalid rewardToken: ${p4.rewardToken}`);
    const nowSec = BigInt(Math.floor(Date.now() / 1e3));
    const startedAt = BigInt(p4.startedAt);
    const deadline = BigInt(p4.deadline);
    if (startedAt >= deadline) {
      throw new Error(`create_staking_tier: startedAt (${p4.startedAt}) must be BEFORE deadline (${p4.deadline}) \u2014 the contract reverts 'SP: Invalid settings'.`);
    }
    if (deadline <= nowSec) {
      throw new Error(`create_staking_tier: deadline ${p4.deadline} (${new Date(Number(deadline) * 1e3).toISOString()}) is in the PAST \u2014 current unix time is ~${nowSec}. The contract would SILENTLY reject the tier at execute (transaction succeeds, no tier is created, the reward returns to the treasury). Use future timestamps computed from the current time \u2014 never guess the date \u2014 and leave headroom for the voting period before execution.`);
    }
    const iface = new Interface(STAKING_PROPOSAL_ABI);
    const createData = iface.encodeFunctionData("createStaking", [
      p4.rewardToken,
      BigInt(p4.rewardAmount),
      BigInt(p4.startedAt),
      BigInt(p4.deadline),
      p4.stakingMetadataUrl
    ]);
    const actionsOnFor = [];
    if (p4.isNative) {
      actionsOnFor.push({ executor: stakingProposal, value: p4.rewardAmount, data: createData });
    } else {
      const erc20 = new Interface(ERC20_GOV_ABI);
      actionsOnFor.push({
        executor: p4.rewardToken,
        value: "0",
        data: erc20.encodeFunctionData("approve", [stakingProposal, BigInt(p4.rewardAmount)])
      });
      actionsOnFor.push({ executor: stakingProposal, value: "0", data: createData });
    }
    return {
      actionsOnFor,
      category: "createStakingTier",
      metadataExtra: changes({
        rewardToken: p4.rewardToken,
        rewardAmount: p4.rewardAmount,
        startedAt: p4.startedAt,
        deadline: p4.deadline,
        metadata: p4.stakingMetadataUrl
      }),
      summary: `Create staking \u2192 ${p4.rewardAmount} of ${p4.rewardToken}`
    };
  }
};
