function buildPayload(opts) {
  const data4 = opts.iface.encodeFunctionData(opts.method, opts.args);
  const value = (opts.value ?? 0n).toString();
  const description = opts.description ?? `${opts.contractLabel ?? "Contract"}.${opts.method}(${formatArgs(opts.args)})`;
  return {
    to: opts.to,
    data: data4,
    value,
    chainId: opts.chainId,
    description
  };
}
function formatArgs(args) {
  return args.map((a3) => {
    if (typeof a3 === "bigint")
      return a3.toString();
    if (typeof a3 === "string")
      return a3.length > 42 ? `${a3.slice(0, 10)}\u2026` : a3;
    if (Array.isArray(a3))
      return `[${a3.length}]`;
    if (a3 && typeof a3 === "object")
      return "{\u2026}";
    return String(a3);
  }).join(", ");
}

