// dist/lib/time.js
function unixToUtc(sec) {
  const n4 = Number(sec);
  if (!Number.isFinite(n4) || n4 <= 0)
    return "";
  return new Date(n4 * 1e3).toISOString().replace("T", " ").replace(/\.\d{3}Z$/, " UTC");
}

