function registerMulticall(server, rpc) {
  server.registerTool("dexe_read_multicall", {
    title: "Arbitrary batched eth_call via Multicall3",
    description: "Execute N independent view calls in a single RPC round-trip. Each call supplies its own ABI signature fragment, target, method, and args. Results are decoded per-call.",
    inputSchema: {
      chainId: chainIdParam,
      calls: external_exports.array(external_exports.object({
        target: external_exports.string(),
        signature: external_exports.string().describe("Full function signature, e.g. 'function balanceOf(address) view returns (uint256)'"),
        method: external_exports.string().describe("Method name matching the signature"),
        args: external_exports.array(external_exports.unknown()).default([]),
        allowFailure: external_exports.boolean().default(true)
      })).min(1)
    },
    outputSchema: {
      results: external_exports.array(external_exports.object({
        success: external_exports.boolean(),
        value: external_exports.unknown().nullable(),
        raw: external_exports.string(),
        error: external_exports.string().optional()
      }))
    }
  }, async ({ chainId, calls }) => {
    try {
      const pr = rpc.tryProvider(chainId);
      if ("error" in pr)
        return errorResult13(`${pr.error}
${pr.remediation}`);
      const provider = pr.ok;
      const batch = calls.map((c4) => {
        if (!isAddress(c4.target))
          throw new Error(`Invalid target: ${c4.target}`);
        return {
          target: c4.target,
          iface: new Interface([c4.signature]),
          method: c4.method,
          args: c4.args.map(coerceArg),
          allowFailure: c4.allowFailure
        };
      });
      const results = await multicall(provider, batch);
      const structured = {
        results: results.map((r2) => ({
          success: r2.success,
          value: jsonSafe(r2.value),
          raw: r2.raw,
          error: r2.error
        }))
      };
      return untrustedResult({
        summary: `${results.length} calls: ${results.filter((r2) => r2.success).length} ok, ${results.filter((r2) => !r2.success).length} failed`,
        label: "decoded return values (contract-authored)",
        structured
      });
    } catch (err13) {
      return errorResult13(toActionableError(err13, "dexe_read_multicall").message);
    }
  });
}
