function downsample(rows2, max) {
  if (rows2.length <= max)
    return rows2;
  const out = [];
  const step = (rows2.length - 1) / (max - 1);
  for (let i3 = 0; i3 < max; i3++)
    out.push(rows2[Math.round(i3 * step)]);
  return out;
}
