function registerExecute(server, ctx, rpc) {
  server.registerTool("dexe_vote_build_execute", {
    title: "Execute a passed proposal",
    description: "Builds `GovPool.execute(proposalId)`; scope:'internal' + govValidators builds `GovValidators.executeInternalProposal(proposalId)` (anyone can send once Succeeded).",
    inputSchema: {
      govPool: external_exports.string(),
      proposalId: external_exports.string(),
      scope: external_exports.enum(["external", "internal"]).default("external"),
      govValidators: external_exports.string().optional().describe("Required for scope:'internal' (dexe_dao_info.helpers.validators)"),
      voter: voterParam,
      chainId: buildChainIdParam
    },
    outputSchema: payloadOutputSchema3()
  }, async ({ govPool, proposalId, scope = "external", govValidators, voter, chainId }) => {
    if (!isAddress(govPool))
      return errorResult15(`Invalid govPool: ${govPool}`);
    const targetChain = chainId ?? ctx.config.defaultChainId;
    const lockAdvisory = await depositLockAdvisory(rpc, {
      govPool,
      voter,
      chainId: targetChain,
      fallback: POST_EXECUTE_LOCK_ADVISORY
    });
    try {
      if (scope === "internal") {
        if (!govValidators || !isAddress(govValidators)) {
          return errorResult15("scope:'internal' requires `govValidators` (get it from dexe_dao_info.helpers.validators).");
        }
        const vIface = new Interface(["function executeInternalProposal(uint256 proposalId)"]);
        const payload2 = buildPayload({
          to: govValidators,
          iface: vIface,
          method: "executeInternalProposal",
          args: [parseUintString(proposalId, "proposalId")],
          chainId: targetChain,
          contractLabel: "GovValidators",
          description: `GovValidators.executeInternalProposal(#${proposalId})`
        });
        return payloadResult2(payload2, lockAdvisory);
      }
      const iface = new Interface(GOV_POOL_WRITE_ABI);
      const payload = buildPayload({
        to: govPool,
        iface,
        method: "execute",
        args: [parseUintString(proposalId, "proposalId")],
        chainId: targetChain,
        contractLabel: "GovPool",
        description: `GovPool.execute(#${proposalId})`
      });
      return payloadResult2(payload, executeAddSettingsAdvisory(targetChain), lockAdvisory);
    } catch (err13) {
      return errorResult15(safeErrorMessage(err13));
    }
  });
}
