// dist/governor/tools/simulate.js
init_zod();
init_lib2();
init_redact();
var ERROR_STRING_SELECTOR2 = "0x08c379a0";
var PANIC_SELECTOR2 = "0x4e487b71";
function ok13(data4) {
  return { content: [{ type: "text", text: JSON.stringify(data4, null, 2) }] };
}
function err11(message) {
  return { content: [{ type: "text", text: message }], isError: true };
}
function decodeRevert2(data4) {
  if (!data4 || data4 === "0x")
    return null;
  if (data4.startsWith(ERROR_STRING_SELECTOR2)) {
    try {
      const iface = new Interface(["function Error(string)"]);
      const [reason] = iface.decodeFunctionData("Error", data4);
      return reason;
    } catch {
      try {
        return toUtf8String("0x" + data4.slice(10 + 64 + 64));
      } catch {
        return data4;
      }
    }
  }
  if (data4.startsWith(PANIC_SELECTOR2)) {
    try {
      const code6 = BigInt("0x" + data4.slice(10));
      const known = {
        "1": "assert(false)",
        "17": "arithmetic overflow/underflow",
        "18": "division or modulo by zero",
        "33": "invalid enum conversion",
        "34": "invalid storage byte array access",
        "49": "pop() on empty array",
        "50": "array index out of bounds",
        "65": "out-of-memory allocation",
        "81": "call to uninitialized internal function"
      };
      const hint = known[code6.toString()];
      return `Panic(0x${code6.toString(16)})${hint ? ` \u2014 ${hint}` : ""}`;
    } catch {
      return `Panic(${data4.slice(10)})`;
    }
  }
  return data4;
}
var governorIdSchema3 = external_exports.string().min(1).describe("Governor id (e.g. 'uniswap', 'compound', 'optimism') or 0x-prefixed governor contract address.");
var uintLikeSchema2 = external_exports.union([external_exports.string(), external_exports.number()]);
